import React from "react";
import { AbsoluteFill, useCurrentFrame, interpolate, Easing } from "remotion";
import { useSvgFrames } from "../motion";

export const fps = 25;
export const durationInFrames = 75;

// MCP1 viewBox: 3442 x 1114 (original closed box)
// MCP2 viewBox: 3442 x 1334 (extended box with new content)
// Top 1114 px of MCP2 == MCP1 visually (UI mockup convention).

const MCP1_VB_H = 1114;
const MCP2_VB_W = 3442;
const MCP2_VB_H = 1334;

const CANVAS_W = 3840;
const CANVAS_H = 2160;

// Fit-to-width: scale so SVG width fills canvas, keep aspect ratio.
const SCALE = CANVAS_W / MCP2_VB_W;
const MCP1_RENDER_H = MCP1_VB_H * SCALE;
const MCP2_RENDER_H = MCP2_VB_H * SCALE;

// Vertically center MCP2's full height in the canvas (MCP1 sits at the same top).
const TOP = (CANVAS_H - MCP2_RENDER_H) / 2;

const HOLD_START = 8;
const REVEAL_END = 55;

// Make the SVG fill its wrapper (replace fixed width/height with width:100%/height:auto so the viewBox scales).
function stripSize(svg) {
  return svg.replace(
    /<svg[^>]*?>/,
    (m) =>
      m
        .replace(/\swidth="[^"]*"/, "")
        .replace(/\sheight="[^"]*"/, "")
        .replace(
          "<svg",
          '<svg preserveAspectRatio="xMinYMin meet" style="width:100%;height:auto;display:block"'
        )
  );
}

export default function MCPExtend() {
  const frame = useCurrentFrame();
  const svgs = useSvgFrames();
  const mcp2 = svgs[1];
  if (!mcp2) return null;

  const t = interpolate(frame, [HOLD_START, REVEAL_END], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.cubic),
  });

  // Wrapper height grows from MCP1's rendered height to MCP2's rendered height.
  // MCP2 inside is top-anchored at its full natural size; overflow:hidden cuts the bottom
  // off initially. As the wrapper expands, the new rows (and the lower box edge) reveal.
  const wrapperH = MCP1_RENDER_H + (MCP2_RENDER_H - MCP1_RENDER_H) * t;

  return (
    <AbsoluteFill>
      <div
        style={{
          position: "absolute",
          left: 0,
          top: TOP,
          width: CANVAS_W,
          height: wrapperH,
          overflow: "hidden",
        }}
      >
        <div
          style={{
            position: "absolute",
            left: 0,
            top: 0,
            width: CANVAS_W,
          }}
          dangerouslySetInnerHTML={{ __html: stripSize(mcp2.content) }}
        />
      </div>
    </AbsoluteFill>
  );
}
